// Approximate USD price per 1M tokens by model family.
// Anthropic's messages usage report returns TOKEN counts, not cost, so we
// estimate cost from published list prices. Adjust these if your rates differ.
const PRICES = [
  { match: 'opus',   inPer1M: 15.00, outPer1M: 75.00 },
  { match: 'sonnet', inPer1M: 3.00,  outPer1M: 15.00 },
  { match: 'haiku',  inPer1M: 0.80,  outPer1M: 4.00 },
];
const DEFAULT_PRICE = { inPer1M: 3.00, outPer1M: 15.00 };
function priceFor(model) {
  const m = (model || '').toLowerCase();
  return PRICES.find((p) => m.includes(p.match)) || DEFAULT_PRICE;
}

// Lifetime is bounded by the fetch start date in the HTTP node.
const LIFETIME_SINCE = '2024-01-01';

const NL = String.fromCharCode(10);
const fmt = (n) => Number(n).toLocaleString('en-US');

// Cutoffs based on COMPLETE days in UTC (today is excluded by ending_at).
const now = new Date();
const startOfTodayUTC = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const DAY = 86400000;
const dailyStart = startOfTodayUTC - DAY;        // yesterday 00:00 UTC
const weeklyStart = startOfTodayUTC - 7 * DAY;   // last 7 complete days
const monthlyStart = startOfTodayUTC - 30 * DAY; // last 30 complete days

function addTo(agg, model, inTok, outTok) {
  if (!agg[model]) agg[model] = { model, inputTokens: 0, outputTokens: 0 };
  agg[model].inputTokens += inTok;
  agg[model].outputTokens += outTok;
}

const daily = {};
const weekly = {};
const monthly = {};
const lifetime = {};

// Each input item is one HTTP page: { data: [ { starting_at, ending_at, results: [...] } ] }
for (const item of $input.all()) {
  const buckets = (item.json && item.json.data) || [];
  for (const bucket of buckets) {
    const startMs = Date.parse(bucket.starting_at);
    for (const r of bucket.results || []) {
      const model = r.model || 'unknown';
      const inTok =
        (r.uncached_input_tokens || 0) +
        (r.cache_creation_input_tokens || 0) +
        (r.cache_read_input_tokens || 0) +
        (r.input_tokens || 0);
      const outTok = r.output_tokens || 0;
      addTo(lifetime, model, inTok, outTok);
      if (startMs >= monthlyStart) addTo(monthly, model, inTok, outTok);
      if (startMs >= weeklyStart) addTo(weekly, model, inTok, outTok);
      if (startMs >= dailyStart && startMs < startOfTodayUTC) addTo(daily, model, inTok, outTok);
    }
  }
}

function summarize(agg) {
  const rows = Object.values(agg).map((row) => {
    const p = priceFor(row.model);
    const estCost = (row.inputTokens / 1e6) * p.inPer1M + (row.outputTokens / 1e6) * p.outPer1M;
    return {
      ...row,
      totalTokens: row.inputTokens + row.outputTokens,
      estCostUsd: Math.round(estCost * 100) / 100,
    };
  });
  rows.sort((a, b) => b.estCostUsd - a.estCostUsd);
  const totals = rows.reduce(
    (a, r) => {
      a.inputTokens += r.inputTokens;
      a.outputTokens += r.outputTokens;
      a.totalTokens += r.totalTokens;
      a.estCostUsd += r.estCostUsd;
      return a;
    },
    { inputTokens: 0, outputTokens: 0, totalTokens: 0, estCostUsd: 0 },
  );
  totals.estCostUsd = Math.round(totals.estCostUsd * 100) / 100;
  return { rows, totals };
}

const D = summarize(daily);
const W = summarize(weekly);
const M = summarize(monthly);
const L = summarize(lifetime);

const dailyLabel = new Date(dailyStart).toISOString().slice(0, 10);

function totalsLine(s) {
  return '*' + fmt(s.totals.totalTokens) + '* tokens \u00b7 *$' + s.totals.estCostUsd.toFixed(2) +
    '*  _(' + fmt(s.totals.inputTokens) + ' in / ' + fmt(s.totals.outputTokens) + ' out)_';
}

const blocks = [];
blocks.push({ type: 'header', text: { type: 'plain_text', text: 'Anthropic API usage — ' + dailyLabel } });

// Daily section with per-model breakdown
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*:calendar: Daily (' + dailyLabel + ')*' + NL + totalsLine(D) } });
if (D.rows.length) {
  let detail = '';
  for (const r of D.rows) {
    detail += '\u2022 *' + r.model + '* — ' + fmt(r.totalTokens) + ' tok \u00b7 $' + r.estCostUsd.toFixed(2) + NL;
  }
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: detail.trim() } });
} else {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '_No usage recorded for this day._' } });
}

blocks.push({ type: 'divider' });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*:date: Last 7 days*' + NL + totalsLine(W) } });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*:spiral_calendar_pad: Last 30 days*' + NL + totalsLine(M) } });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*:infinity: Lifetime (since ' + LIFETIME_SINCE + ')*' + NL + totalsLine(L) } });
blocks.push({
  type: 'context',
  elements: [
    {
      type: 'mrkdwn',
      text: 'Cost is estimated from list prices in the Code node. Lifetime is bounded by the fetch start date (' + LIFETIME_SINCE + ') — change it in the Code node and HTTP node to go further back.',
    },
  ],
});

return [
  {
    json: {
      dailyLabel,
      daily: D,
      weekly: W,
      monthly: M,
      lifetime: L,
      blocksUi: { blocks },
    },
  },
];
